// src/segmentTree.ts
var nodeId = (left, right) => `${left}-${right}`;
function buildTree(values3) {
  const nodes = [];
  const build = (left, right, depth, parentId) => {
    const id = nodeId(left, right);
    const middle = Math.floor((left + right) / 2);
    const sum = left === right ? values3[left] : build(left, middle, depth + 1, id) + build(middle + 1, right, depth + 1, id);
    nodes.push({
      id,
      left,
      right,
      sum,
      depth,
      x: (left + right + 1) / 2 / values3.length * 100,
      y: 12 + depth * 23,
      parentId
    });
    return sum;
  };
  build(0, values3.length - 1, 0);
  return nodes.sort((a, b) => a.depth - b.depth || a.left - b.left);
}
function createQueryTrace(values3, queryLeft, queryRight) {
  const nodes = buildTree(values3);
  const statuses = Object.fromEntries(nodes.map((node) => [node.id, "idle"]));
  const returnedValues = {};
  const steps = [];
  let runningTotal = 0;
  let sequence = 0;
  const push = (step) => {
    steps.push({
      ...step,
      id: `${sequence++}-${step.kind}-${step.activeId ?? "scene"}`,
      statuses: { ...statuses },
      returnedValues: { ...returnedValues },
      runningTotal
    });
  };
  push({
    kind: "start",
    title: `\u67E5\u8A62 [${queryLeft + 1}, ${queryRight + 1}]`,
    explanation: "\u5149\u5E36\u6A19\u51FA\u76EE\u6A19\u7BC4\u570D\u3002\u63A5\u8457\u5F9E\u4EE3\u8868\u6574\u500B\u9663\u5217\u7684\u6839\u7BC0\u9EDE\u958B\u59CB\u3002"
  });
  const query = (left, right) => {
    const id = nodeId(left, right);
    statuses[id] = "active";
    push({
      kind: "visit",
      activeId: id,
      title: `\u67E5\u770B [${left + 1}, ${right + 1}]`,
      explanation: `\u76EE\u524D\u7BC0\u9EDE\u6DB5\u84CB\u7B2C ${left + 1} \u5230 ${right + 1} \u500B\u5143\u7D20\uFF0C\u5148\u6BD4\u8F03\u5B83\u548C\u67E5\u8A62\u7BC4\u570D\u3002`
    });
    if (right < queryLeft || left > queryRight) {
      statuses[id] = "ignored";
      returnedValues[id] = 0;
      push({
        kind: "ignore",
        activeId: id,
        title: "\u6C92\u6709\u91CD\u758A",
        explanation: "\u9019\u6BB5\u5B8C\u5168\u5728\u67E5\u8A62\u7BC4\u570D\u4E4B\u5916\uFF0C\u4E0D\u6703\u8CA2\u737B\u7B54\u6848\uFF0C\u76F4\u63A5\u56DE\u50B3 0\u3002"
      });
      return 0;
    }
    const node = nodes.find((item) => item.id === id);
    if (queryLeft <= left && right <= queryRight) {
      statuses[id] = "accepted";
      returnedValues[id] = node.sum;
      runningTotal += node.sum;
      push({
        kind: "accept",
        activeId: id,
        title: `\u5B8C\u6574\u5305\u542B \xB7 \u53D6\u7528 ${node.sum}`,
        explanation: `\u6574\u6BB5\u90FD\u5728\u67E5\u8A62\u7BC4\u570D\u5167\uFF0C\u53EF\u4EE5\u76F4\u63A5\u4F7F\u7528\u7BC0\u9EDE\u9810\u5148\u5B58\u597D\u7684\u7E3D\u548C ${node.sum}\u3002`
      });
      return node.sum;
    }
    statuses[id] = "partial";
    push({
      kind: "partial",
      activeId: id,
      title: "\u90E8\u5206\u91CD\u758A \xB7 \u7E7C\u7E8C\u5F80\u4E0B",
      explanation: "\u9019\u6BB5\u53EA\u6709\u4E00\u90E8\u5206\u843D\u5728\u76EE\u6A19\u7BC4\u570D\uFF0C\u5FC5\u9808\u62C6\u6210\u5DE6\u53F3\u5169\u534A\u5206\u5225\u67E5\u8A62\u3002"
    });
    const middle = Math.floor((left + right) / 2);
    const value = query(left, middle) + query(middle + 1, right);
    statuses[id] = "returned";
    returnedValues[id] = value;
    push({
      kind: "return",
      activeId: id,
      title: `\u5408\u4F75\u7D50\u679C \xB7 ${value}`,
      explanation: `\u5DE6\u53F3\u5B50\u6A39\u7684\u7D50\u679C\u76F8\u52A0\u70BA ${value}\uFF0C\u73FE\u5728\u628A\u9019\u500B\u5C0F\u8A08\u5F80\u4E0A\u4E00\u5C64\u50B3\u3002`
    });
    return value;
  };
  const total = query(0, values3.length - 1);
  statuses[nodeId(0, values3.length - 1)] = "returned";
  push({
    kind: "complete",
    activeId: nodeId(0, values3.length - 1),
    title: `\u67E5\u8A62\u5B8C\u6210 \xB7 ${total}`,
    explanation: `\u6240\u6709\u9700\u8981\u7684\u5340\u6BB5\u90FD\u5DF2\u5408\u4F75\uFF0C\u5340\u9593\u7E3D\u548C\u662F ${total}\u3002`
  });
  return steps;
}

