  { id: "sliding-window-maximum", categoryId: "linear-structures", subcategory: "Queue \u8207 Deque", category: "DEQUE", title: "Sliding Window Maximum", zhTitle: "\u6ED1\u52D5\u8996\u7A97\u6700\u5927\u503C", description: "\u55AE\u8ABF Deque \u4FDD\u5B58\u672A\u88AB\u652F\u914D\u7684\u5019\u9078\u7D22\u5F15\u3002", complexity: "O(n)", visual: "linear", accent: linear, code: ["deque<int> dq;", "for(int i=0;i<n;++i){", "  while(!dq.empty() && dq.front()<=i-k) dq.pop_front();", "  while(!dq.empty() && a[dq.back()]<=a[i]) dq.pop_back();", "  dq.push_back(i); if(i>=k-1) answer.push_back(a[dq.front()]);", "}"], concepts: ["deque \u7D22\u5F15\u905E\u589E\u3001\u5C0D\u61C9\u503C\u56B4\u683C\u905E\u6E1B\uFF1Bfront \u56E0\u6B64\u662F\u76EE\u524D\u8996\u7A97\u6700\u5927\u503C\u3002", "\u5148\u5F9E front \u79FB\u9664\u96E2\u958B\u8996\u7A97\u8005\uFF1B\u518D\u5F9E back \u79FB\u9664\u4E0D\u5927\u65BC\u65B0\u503C\u8005\uFF0C\u56E0\u65B0\u503C\u66F4\u665A\u904E\u671F\u4E14\u81F3\u5C11\u540C\u5927\u3002", "\u6BCF\u500B\u7D22\u5F15\u6700\u591A\u9032\u51FA\u4E00\u6B21\uFF0Cfront \u59CB\u7D42\u662F\u4ECD\u5728\u8996\u7A97\u5167\u7684\u6700\u5927\u5019\u9078\uFF0C\u56E0\u6B64\u6240\u6709\u8996\u7A97\u7B54\u6848\u53EF\u5728\u7DDA\u6027\u6642\u9593\u4F9D\u5E8F\u7522\u751F\u3002"], states: ["indices increasing, values decreasing", "expire front / dominate back", "front is each window maximum"] },
  { id: "expression-evaluation", categoryId: "linear-structures", subcategory: "Stack", category: "STACK", title: "Expression Evaluation", zhTitle: "\u904B\u7B97\u5F0F\u6C42\u503C", description: "\u4EE5\u6578\u503C\u8207\u904B\u7B97\u5B50 Stack \u5BE6\u4F5C\u512A\u5148\u5E8F\u3002", complexity: "O(n)", visual: "linear", accent: linear, code: ["for(Token t:tokens){", "  if(isNumber(t)) values.push(t.value);", '  else if(t=="(") ops.push(t);', "  else { while(shouldReduce(ops.top(),t)) applyTop(values,ops); ops.push(t); }", "}", "while(!ops.empty()) applyTop(values,ops);"], concepts: ["values \u4FDD\u5B58\u5DF2\u8B80\u904B\u7B97\u5143\u8207\u90E8\u5206\u7D50\u679C\uFF0Cops \u4FDD\u5B58\u5C1A\u672A\u5957\u7528\u7684\u904B\u7B97\u5B50\uFF1B\u62EC\u865F\u5F62\u6210\u4E0D\u53EF\u8DE8\u8D8A\u7684\u754C\u7DDA\u3002", "\u65B0\u904B\u7B97\u5B50\u5230\u4F86\u6642\uFF0C\u5148\u7D50\u7B97\u512A\u5148\u5E8F\u66F4\u9AD8\u6216\u540C\u7D1A\u5DE6\u7D50\u5408\u7684 stack top\uFF0C\u78BA\u4FDD\u539F\u904B\u7B97\u9806\u5E8F\u3002", "\u6BCF\u500B token push/pop \u5E38\u6578\u6B21\uFF1B\u5B8C\u6574\u8B80\u53D6\u4E26\u6E05\u7A7A ops \u5F8C\uFF0Cvalues top \u662F\u552F\u4E00\u7D50\u679C\u3002"], states: ["operand and operator stacks", "reduce by precedence / parentheses", "single final value"] },
  { id: "shunting-yard", categoryId: "linear-structures", subcategory: "Stack", category: "STACK", title: "Shunting Yard", zhTitle: "\u8ABF\u5EA6\u5834\u6F14\u7B97\u6CD5", description: "\u5C07\u4E2D\u5E8F\u904B\u7B97\u5F0F\u8F49\u70BA\u5F8C\u5E8F\u5E8F\u5217\u3002", complexity: "O(n)", visual: "linear", accent: linear, code: ["for(Token t:tokens){", "  if(isOperand(t)) output.push_back(t);", "  else if(isOperator(t)){ while(higherPrecedenceOnStack(t)) popToOutput(); ops.push(t); }", '  else if(t=="(") ops.push(t); else { while(ops.top()!="(") popToOutput(); ops.pop(); }', "}", "while(!ops.empty()) popToOutput();"], concepts: ["\u5F8C\u5E8F\u8F38\u51FA\u4E2D\u904B\u7B97\u5143\u5148\u65BC\u4F7F\u7528\u5B83\u7684\u904B\u7B97\u5B50\uFF1Boperator stack \u5EF6\u9072\u5C1A\u4E0D\u80FD\u78BA\u5B9A\u4F4D\u7F6E\u7684\u7B26\u865F\u3002", "\u9047\u5230\u904B\u7B97\u5B50\u6642\uFF0C\u628A\u61C9\u5148\u57F7\u884C\u7684 stack \u904B\u7B97\u5B50\u8F38\u51FA\uFF1B\u53F3\u62EC\u865F\u5247\u8F38\u51FA\u76F4\u5230\u5C0D\u61C9\u5DE6\u62EC\u865F\u4F46\u4E0D\u8F38\u51FA\u62EC\u865F\u3002", "\u8F38\u51FA\u5E8F\u5217\u53EF\u7528\u55AE\u4E00\u503C stack \u7DDA\u6027\u6C42\u503C\uFF0C\u4E14\u5B8C\u5168\u4FDD\u7559\u539F\u512A\u5148\u5E8F\u8207\u7D50\u5408\u6027\u3002"], states: ["operators wait on stack", "pop by precedence and parentheses", "valid postfix sequence"] }
