var binaryCode = [
  "int binarySearch(vector<int>& a, int target) {",
  "  int low = 0, high = (int)a.size() - 1;",
  "  while (low <= high) {",
  "    int mid = low + (high - low) / 2;",
  "    if (a[mid] == target)",
  "      return mid;",
  "    if (a[mid] < target)",
  "      low = mid + 1;",
  "    else",
  "      high = mid - 1;",
  "  }",
  "  return -1;",
  "}"
];
var bfsCode = [
  "void bfs(int source) {",
  "  queue<int> q;",
  "  vector<int> dist(n, -1);",
  "  q.push(source);",
  "  visited[source] = true;",
  "  dist[source] = 0;",
  "  while (!q.empty()) {",
  "    int u = q.front();",
  "    q.pop();",
  "    for (int v : graph[u]) {",
  "      if (visited[v]) continue;",
  "      dist[v] = dist[u] + 1;",
  "      visited[v] = true;",
  "      q.push(v);",
  "    }",
  "  }",
  "}"
];
var dijkstraCode = [
  "void dijkstra(int source) {",
  "  using State = pair<long long, int>;",
  "  priority_queue<State, vector<State>, greater<State>> pq;",
  "  fill(dist.begin(), dist.end(), INF);",
  "  dist[source] = 0;",
  "  pq.push({0, source});",
  "  while (!pq.empty()) {",
  "    auto [d, u] = pq.top();",
  "    pq.pop();",
  "    if (d != dist[u]) continue;",
  "    for (auto [v, w] : graph[u]) {",
  "      if (d + w < dist[v]) {",
  "        dist[v] = d + w;",
  "        pq.push({dist[v], v});",
  "      }",
  "    }",
  "  }",
  "}"
];
var segmentCode = [
  "struct SegmentTree {",
  "  int n;",
  "  vector<long long> tree;",
  "  explicit SegmentTree(const vector<long long>& a) : n(a.size()), tree(4 * max(1, n), 0) {",
  "    if (n) build(1, 0, n - 1, a);",
  "  }",
  "  void build(int node, int l, int r, const vector<long long>& a) {",
  "    if (l == r) { tree[node] = a[l]; return; }",
  "    int mid = l + (r - l) / 2;",
  "    build(node * 2, l, mid, a);",
  "    build(node * 2 + 1, mid + 1, r, a);",
  "    tree[node] = tree[node * 2] + tree[node * 2 + 1];",
  "  }",
  "  long long query(int node, int l, int r, int ql, int qr) const {",
  "    if (r < ql || qr < l) return 0;",
  "    if (ql <= l && r <= qr) return tree[node];",
  "    int mid = l + (r - l) / 2;",
  "    long long left = query(node * 2, l, mid, ql, qr);",
  "    long long right = query(node * 2 + 1, mid + 1, r, ql, qr);",
  "    return left + right;",
  "  }",
  "  long long query(int l, int r) const { return n ? query(1, 0, n - 1, l, r) : 0; }",
  "  void update(int node, int l, int r, int index, long long value) {",
  "    if (l == r) { tree[node] = value; return; }",
  "    int mid = l + (r - l) / 2;",
  "    if (index <= mid) update(node * 2, l, mid, index, value);",
  "    else update(node * 2 + 1, mid + 1, r, index, value);",
  "    tree[node] = tree[node * 2] + tree[node * 2 + 1];",
  "  }",
  "  void update(int index, long long value) { if (n) update(1, 0, n - 1, index, value); }",
  "};"
];
var hullCode = [
  "vector<Point> convexHull(vector<Point> p) {",
  "  sort(p.begin(), p.end());",
  "  vector<Point> lower, upper;",
  "  for (Point x : p) {",
  "    while (lower.size() >= 2 &&",
  "           cross(lower.end()[-2], lower.back(), x) <= 0)",
  "      lower.pop_back();",
  "    lower.push_back(x);",
  "  }",
  "  reverse(p.begin(), p.end());",
  "  // build upper using the same loop",
  "  lower.pop_back(); upper.pop_back();",
  "  lower.insert(lower.end(), upper.begin(), upper.end());",
  "  return lower;",
  "}"
];
